        self._append_prompt("Reset and re-split cleanly into tokens and parser", "2026-09-04T10:10:00Z")
        subprocess.run(["git", "reset", "--soft", "HEAD~2"], cwd=self.repo_dir, check=True)

        # Author replacement commits
        sha_new1 = self._commit("tokens.txt", "tokens", "feat: Tokens")
        sha_new2 = self._commit("parser.txt", "parser_clean", "feat: Clean Parser")

        # Both replacement commits must preserve the full session history with causal prompt at top!
        note_new1 = gpn.parse_notes(gpn.get_note_content(sha_new1, repo_root=self.repo_dir))[0]
        note_new2 = gpn.parse_notes(gpn.get_note_content(sha_new2, repo_root=self.repo_dir))[0]

        self.assertEqual(len(note_new1.prompts), 3)
        self.assertEqual(note_new1.prompts[0].text, "Reset and re-split cleanly into tokens and parser")
        self.assertEqual(note_new1.prompts[1].text, "First attempt at AST")
        self.assertEqual(note_new1.prompts[2].text, "First attempt at parser")

        self.assertEqual(len(note_new2.prompts), 3)
        self.assertEqual(note_new2.prompts[0].text, "Reset and re-split cleanly into tokens and parser")

        # Log command displays cleanly
        out_log = subprocess.check_output(
            ["python3", str(Path(gpn.__file__).resolve()), "log"],
            cwd=self.repo_dir,
            text=True,
            env=self.env,
        )
        self.assertIn("feat: Clean Parser", out_log)
        self.assertIn("Reset and re-split cleanly into tokens and parser", out_log)

        # Verify color formatting in log
        out_color = subprocess.check_output(
            ["python3", str(Path(gpn.__file__).resolve()), "log", "--color=always"],
            cwd=self.repo_dir,
            text=True,
            env=self.env,
        )
        self.assertIn("\033[33m", out_color)
        self.assertIn("\033[36m", out_color)
        self.assertIn("\033[0m", out_color)

        out_no_color = subprocess.check_output(
            ["python3", str(Path(gpn.__file__).resolve()), "log", "--color=never"],
            cwd=self.repo_dir,
            text=True,
            env=self.env,
        )
        self.assertNotIn("\033[33m", out_no_color)
        self.assertNotIn("\033[36m", out_no_color)

