        db_path = self.work_dir / "opencode_sess.db"
        sessions = [
            ("ses_drop_1", "p1", None, "slug-d", str(repo_dir), "Drop Session", "1.18.30", 1789074000000, 1789074200000, "build", "m1")
        ]
