    def test_plain_invocation_defaults_to_log(self):
        repo_dir = self.work_dir / "repo_plain_log"
        repo_dir.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=repo_dir, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=repo_dir, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.com"], cwd=repo_dir, check=True)

        f = repo_dir / "hello.txt"
        f.write_text("hello world")
        subprocess.run(["git", "add", "hello.txt"], cwd=repo_dir, check=True)
        subprocess.run(["git", "commit", "-m", "feat: initial commit"], cwd=repo_dir, check=True)

        script_path = str(bin_path)

        # Attach a prompt note
        cmd_rec = [
            "python3",
            script_path,
            "record",
            "-m",
            "Initial prompt steering",
            "-c",
            "HEAD",
        ]
        subprocess.run(cmd_rec, cwd=repo_dir, check=True, capture_output=True)

        # 1. Run plain git-prompt-log
        res_plain = subprocess.run(
            ["python3", script_path],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )

        # 2. Run explicit git-prompt-log log
        res_log = subprocess.run(
            ["python3", script_path, "log"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )

        # Plain git-prompt-log must match git-prompt-log log output exactly
        self.assertEqual(res_plain.returncode, 0)
        self.assertEqual(res_log.returncode, 0)
        self.assertEqual(res_plain.stdout, res_log.stdout)
        self.assertIn("feat: initial commit", res_plain.stdout)
        self.assertIn("Initial prompt steering", res_plain.stdout)

        # 3. Verify --help shows namespaced shorthand options without unnamespaced --ref or --color
        res_help = subprocess.run(
            ["python3", script_path, "--help"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )
        self.assertIn("Display commits with their steering prompts (default)", res_help.stdout)
        self.assertIn("--prompt-full", res_help.stdout)
        self.assertIn("--prompt-ref", res_help.stdout)
        self.assertNotIn("--ref REF", res_help.stdout)
        self.assertNotIn("--color {always,never,auto}", res_help.stdout)

        # 4. Verify shorthand supports namespaced flags and forwarded options
        res_shorthand_full = subprocess.run(
            ["python3", script_path, "--prompt-full"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )
        self.assertEqual(res_shorthand_full.returncode, 0)
        self.assertIn("Initial prompt steering", res_shorthand_full.stdout)

        res_shorthand_count = subprocess.run(
            ["python3", script_path, "-n", "1"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )
        self.assertEqual(res_shorthand_count.returncode, 0)
        self.assertIn("feat: initial commit", res_shorthand_count.stdout)

        res_shorthand_stat = subprocess.run(
            ["python3", script_path, "--stat"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )
        self.assertEqual(res_shorthand_stat.returncode, 0)
        self.assertIn("hello.txt", res_shorthand_stat.stdout)

        # 5. Verify invalid command still produces error
        res_invalid = subprocess.run(
            ["python3", script_path, "unknown-cmd"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
        )
        self.assertEqual(res_invalid.returncode, 2)

    def test_log_placeholder_when_no_prompts(self):
        repo_dir = self.work_dir / "repo_log_placeholder"
        repo_dir.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=repo_dir, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=repo_dir, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.com"], cwd=repo_dir, check=True)

        script_path = str(bin_path)

        # Commit 1: No prompts recorded
        f1 = repo_dir / "file1.txt"
        f1.write_text("file1 content")
        subprocess.run(["git", "add", "file1.txt"], cwd=repo_dir, check=True)
        subprocess.run(["git", "commit", "-m", "chore: unprompted commit"], cwd=repo_dir, check=True)

        # Commit 2: With prompt note
        f2 = repo_dir / "file2.txt"
        f2.write_text("file2 content")
        subprocess.run(["git", "add", "file2.txt"], cwd=repo_dir, check=True)
        subprocess.run(["git", "commit", "-m", "feat: prompted commit"], cwd=repo_dir, check=True)
        subprocess.run(
            ["python3", script_path, "record", "-m", "Steering prompt for commit 2", "-c", "HEAD"],
            cwd=repo_dir,
            check=True,
            capture_output=True,
        )

        res_log = subprocess.run(
            ["python3", script_path, "log"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )

        self.assertIn("feat: prompted commit", res_log.stdout)
        self.assertIn("Steering prompt for commit 2", res_log.stdout)
        self.assertIn("chore: unprompted commit", res_log.stdout)
        self.assertIn("none recorded", res_log.stdout)

        # Check structure: unprompted commit has Prompt: none recorded in its block
        lines = res_log.stdout.splitlines()
        found_unprompted = False
        found_placeholder = False
        for i, line in enumerate(lines):
            if "chore: unprompted commit" in line:
                found_unprompted = True
                block = "\n".join(lines[i:i + 6])
                self.assertIn("Prompt:", block)
                self.assertIn("none recorded", block)
                found_placeholder = True
                break
        self.assertTrue(found_unprompted)
        self.assertTrue(found_placeholder)

    def test_worktree_session_detection(self):
        # 1. Setup main repository
        main_repo = self.work_dir / "main_repo"
        main_repo.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=main_repo, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=main_repo, check=True)
