class TestSessionTimelineWithCommits(unittest.TestCase):
    def setUp(self):
        self.tmp_dir = tempfile.TemporaryDirectory()
        self.work_dir = Path(self.tmp_dir.name)
        self.repo_dir = self.work_dir / "repo"
        self.repo_dir.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=self.repo_dir, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=self.repo_dir, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.com"], cwd=self.repo_dir, check=True)

        self.session_id = "test-timeline-session-1234"
        self.brain_dir = self.work_dir / "brain"
        self.logs_dir = self.brain_dir / self.session_id / ".system_generated" / "logs"
        self.logs_dir.mkdir(parents=True, exist_ok=True)
        self.transcript_file = self.logs_dir / "transcript.jsonl"

        self.env = os.environ.copy()
        self.env["PATH"] = f"{bin_path.parent}:{self.env.get('PATH', '')}"
        self.env["ANTIGRAVITY_DATA_DIR"] = str(self.work_dir)
        self.env["AGY_SESSION_ID"] = self.session_id

        # Initial commit on main
        (self.repo_dir / "base.txt").write_text("base")
        subprocess.run(["git", "add", "base.txt"], cwd=self.repo_dir, check=True)
        subprocess.run(["git", "commit", "-m", "chore: initial base"], cwd=self.repo_dir, env=self.env, check=True)

        # Checkout branch feature
        subprocess.run(["git", "checkout", "-b", "feature"], cwd=self.repo_dir, check=True, capture_output=True)

        # Commit 1 (no note)
        (self.repo_dir / "f1.txt").write_text("f1")
        subprocess.run(["git", "add", "f1.txt"], cwd=self.repo_dir, check=True)
        c_env = self.env.copy()
        c_env["GIT_AUTHOR_DATE"] = "2026-09-04T10:00:00Z"
        c_env["GIT_COMMITTER_DATE"] = "2026-09-04T10:00:00Z"
        subprocess.run(["git", "commit", "-m", "feat: first feature step"], cwd=self.repo_dir, env=c_env, check=True)

        # Commit 2 (will have note recorded)
        (self.repo_dir / "f2.txt").write_text("f2")
        subprocess.run(["git", "add", "f2.txt"], cwd=self.repo_dir, check=True)
        c_env["GIT_AUTHOR_DATE"] = "2026-09-04T10:10:00Z"
        c_env["GIT_COMMITTER_DATE"] = "2026-09-04T10:10:00Z"
        subprocess.run(["git", "commit", "-m", "feat: second feature step"], cwd=self.repo_dir, env=c_env, check=True)

        # Prompts:
        prompts = [
            ("First prompt to start feature", "2026-09-04T09:50:00Z"),
            ("Second prompt to continue feature", "2026-09-04T10:05:00Z"),
            ("Third prompt to conclude work", "2026-09-04T10:15:00Z"),
        ]
        for text, ts in prompts:
            step = {
                "type": "USER_INPUT",
                "source": "USER_EXPLICIT",
                "content": text,
                "created_at": ts,
            }
            with open(self.transcript_file, "a", encoding="utf-8") as f:
                f.write(json.dumps(step) + "\n")

        # Record note only on Commit 2 (HEAD)
        subprocess.run(["python3", str(bin_path), "record", "-c", "HEAD", "--until-prompt", "2"], cwd=self.repo_dir, env=self.env, check=True)

    def tearDown(self):
        self.tmp_dir.cleanup()

    def test_session_timeline_with_explicit_range(self):
        script_path = str(bin_path)
        res = subprocess.run(
            ["python3", script_path, "session", "--commits", "main..feature"],
            cwd=self.repo_dir,
            env=self.env,
            capture_output=True,
            text=True,
            check=True,
        )

        out = res.stdout
        self.assertIn("Session:", out)
        self.assertIn("main..feature", out)

        # Prompts and commits are interleaved
        self.assertIn("[1] 2026-09-04 09:50:00 UTC", out)
        self.assertIn("First prompt to start feature", out)
        self.assertIn("feat: first feature step", out)
        self.assertIn("[note: missing]", out)

        self.assertIn("[2] 2026-09-04 10:05:00 UTC", out)
        self.assertIn("Second prompt to continue feature", out)
        self.assertIn("feat: second feature step", out)
        self.assertIn("[note: recorded]", out)

        self.assertIn("[3] 2026-09-04 10:15:00 UTC", out)
        self.assertIn("Third prompt to conclude work", out)

        # Verify ordering: prompt 1 < commit 1 < prompt 2 < commit 2 < prompt 3
        pos_p1 = out.find("First prompt to start feature")
        pos_c1 = out.find("feat: first feature step")
        pos_p2 = out.find("Second prompt to continue feature")
        pos_c2 = out.find("feat: second feature step")
        pos_p3 = out.find("Third prompt to conclude work")

        self.assertTrue(pos_p1 < pos_c1 < pos_p2 < pos_c2 < pos_p3)

    def test_session_timeline_auto_range(self):
        script_path = str(bin_path)
        res = subprocess.run(
            ["python3", script_path, "session", "--commits"],
            cwd=self.repo_dir,
            env=self.env,
            capture_output=True,
            text=True,
            check=True,
        )
        self.assertIn("Session:", res.stdout)
        self.assertIn("feat: second feature step", res.stdout)


class TestSessionRepoIsolationAndWorktreeDisambiguation(unittest.TestCase):
    def setUp(self):
        self.tmp_dir = tempfile.TemporaryDirectory()
        self.work_dir = Path(self.tmp_dir.name)

        # 1. Setup Repo A
        self.repo_a = self.work_dir / "repo_a"
        self.repo_a.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=self.repo_a, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=self.repo_a, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.com"], cwd=self.repo_a, check=True)
        (self.repo_a / "a.txt").write_text("file in repo a")
        subprocess.run(["git", "add", "."], cwd=self.repo_a, check=True)
        subprocess.run(["git", "commit", "-m", "chore: init repo a"], cwd=self.repo_a, check=True)

        # 2. Setup Repo B with linked worktree
        self.repo_b = self.work_dir / "repo_b"
        self.repo_b.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=self.repo_b, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=self.repo_b, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.com"], cwd=self.repo_b, check=True)
        (self.repo_b / "b.txt").write_text("file in repo b")
        subprocess.run(["git", "add", "."], cwd=self.repo_b, check=True)
        subprocess.run(["git", "commit", "-m", "chore: init repo b"], cwd=self.repo_b, check=True)

        self.wt_b = self.repo_b / ".worktrees" / "feature-b"
        subprocess.run(["git", "worktree", "add", "-b", "feature-b", str(self.wt_b)], cwd=self.repo_b, check=True, capture_output=True)

        self.brain_dir = self.work_dir / "brain"
        self.brain_dir.mkdir(parents=True, exist_ok=True)

    def tearDown(self):
        self.tmp_dir.cleanup()

    def test_repo_a_inspecting_file_with_repo_b_paths_does_not_hijack_repo_b(self):
        # Session A: inside repo A, but views a file or command whose output contains paths to repo B
        sid_a = "session-in-repo-a"
        t_dir_a = self.brain_dir / sid_a / ".system_generated" / "logs"
        t_dir_a.mkdir(parents=True, exist_ok=True)
        (t_dir_a / "transcript.jsonl").write_text("\n".join([
            json.dumps({
                "step_index": 0,
                "source": "USER_EXPLICIT",
                "type": "USER_INPUT",
                "created_at": "2026-09-07T12:00:00Z",
                "content": f"<USER_REQUEST>Inspect dump in {self.repo_a}</USER_REQUEST>",
            }),
            json.dumps({
                "step_index": 1,
                "source": "MODEL",
                "type": "PLANNER_RESPONSE",
                "created_at": "2026-09-07T12:00:01Z",
                "content": f"`[PRE-FLIGHT CHECK]`\n* **Workspace:** {self.repo_a}\n`[END CHECK]`",
                "tool_calls": [{
                    "name": "view_file",
                    "args": {"AbsolutePath": str(self.repo_a / "env.txt"), "toolAction": "viewing dump", "toolSummary": "view env"}
                }]
            }),
            json.dumps({
                "step_index": 2,
                "source": "MODEL",
                "type": "GENERIC",
                "created_at": "2026-09-07T12:00:02Z",
                "content": f"PWD={self.wt_b}\nVSCODE_CWD={self.repo_b}\nfeature-b repo_b neverball",
            }),
        ]), encoding="utf-8")

        # Session B: inside repo B worktree
        sid_b = "session-in-repo-b-worktree"
        t_dir_b = self.brain_dir / sid_b / ".system_generated" / "logs"
        t_dir_b.mkdir(parents=True, exist_ok=True)
        (t_dir_b / "transcript.jsonl").write_text("\n".join([
            json.dumps({
                "step_index": 0,
                "source": "USER_EXPLICIT",
                "type": "USER_INPUT",
                "created_at": "2026-09-07T11:00:00Z", # older timestamp than session A
                "content": "<USER_REQUEST>Work in worktree</USER_REQUEST>",
            }),
            json.dumps({
                "step_index": 1,
                "source": "MODEL",
                "type": "PLANNER_RESPONSE",
                "created_at": "2026-09-07T11:00:01Z",
                "content": f"`[PRE-FLIGHT CHECK]`\n* **Workspace:** {self.wt_b}\n`[END CHECK]`",
                "tool_calls": [{
                    "name": "run_command",
                    "args": {"CommandLine": "ls", "Cwd": str(self.wt_b), "toolAction": "listing", "toolSummary": "ls"}
                }]
            }),
        ]), encoding="utf-8")

        orig_get_brain = gpn.get_brain_dir
        gpn.get_brain_dir = lambda: self.brain_dir
        adapter = gpn.AntigravityAdapter()

        try:
            # 1. Querying Repo B worktree must detect session B even though session A is newer and mentions Repo B in tool output
            detected = adapter.detect_session_id(repo_root=self.wt_b)
            self.assertEqual(detected, sid_b)

            # 2. Ambient conversation ID of session A must be rejected for Repo B
            os.environ["ANTIGRAVITY_CONVERSATION_ID"] = sid_a
            self.assertFalse(adapter.is_active(repo_root=self.wt_b))
            detected_with_ambient = adapter.detect_session_id(repo_root=self.wt_b)
            self.assertEqual(detected_with_ambient, sid_b)

            # 3. Ambient conversation ID of session A must be accepted for Repo A
            self.assertTrue(adapter.is_active(repo_root=self.repo_a))
            self.assertEqual(adapter.detect_session_id(repo_root=self.repo_a), sid_a)

            # 4. Running git prompt-log session CLI in Repo B worktree resolves to Session B
            res = subprocess.run(
                ["python3", str(bin_path), "session"],
                cwd=self.wt_b,
                env=dict(os.environ, ANTIGRAVITY_DATA_DIR=str(self.work_dir), ANTIGRAVITY_CONVERSATION_ID=sid_a),
                capture_output=True,
                text=True,
                check=True,
            )
            self.assertIn(sid_b, res.stdout)
            self.assertNotIn(sid_a, res.stdout)
        finally:
            gpn.get_brain_dir = orig_get_brain
            os.environ.pop("ANTIGRAVITY_CONVERSATION_ID", None)


class TestClaudeSessionCommand(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.repo = Path(self.tmp.name) / "repo"
        self.repo.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=self.repo, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "T"], cwd=self.repo, check=True)
        subprocess.run(["git", "config", "user.email", "t@e.com"], cwd=self.repo, check=True)
        subprocess.run(["python3", str(bin_path), "init"], cwd=self.repo, check=True, capture_output=True)
        # Claude transcript filed in repo/.claude/<sid>.jsonl (a dir _get_claude_dirs scans).
        self.sid = "claude-sess-001"
        cdir = self.repo / ".claude"
        cdir.mkdir()
        (cdir / f"{self.sid}.jsonl").write_text("\n".join([
            json.dumps({"type": "user", "cwd": str(self.repo),
                        "message": {"role": "user", "content": "First real prompt"},
                        "promptSource": "typed", "timestamp": "2026-09-07T10:00:00Z"}),
            json.dumps({"type": "assistant", "message": {"model": "claude-opus-4-8"}}),
            json.dumps({"type": "user", "cwd": str(self.repo),
                        "message": {"role": "user", "content": "Second real prompt"},
                        "promptSource": "typed", "timestamp": "2026-09-07T10:01:00Z"}),
        ]), encoding="utf-8")

    def tearDown(self):
        self.tmp.cleanup()

    def _run_session(self, extra_env=None):
        env = os.environ.copy()
        env["PATH"] = f"{bin_path.parent}:{env.get('PATH', '')}"
        for k in list(env.keys()):
            if "ANTIGRAVITY" in k or "AGY" in k or "GEMINI" in k or "OPENCODE" in k:
                env.pop(k, None)
        empty_brain = Path(self.tmp.name) / "empty_brain"
        empty_brain.mkdir(exist_ok=True)
        env["ANTIGRAVITY_DATA_DIR"] = str(empty_brain)
        env.pop("PROMPT_LOG_HARNESS", None)
        if extra_env:
            env.update(extra_env)
        return subprocess.run(["python3", str(bin_path), "session"],
                              cwd=self.repo, capture_output=True, text=True, env=env)

    def test_session_lists_claude_prompts_plain_shell(self):
        res = self._run_session()
        self.assertEqual(res.returncode, 0, res.stderr)
        self.assertIn("First real prompt", res.stdout)
        self.assertIn("Second real prompt", res.stdout)

    def test_session_lists_claude_prompts_with_session_env(self):
        res = self._run_session({"CLAUDE_CODE_SESSION_ID": self.sid})
        self.assertEqual(res.returncode, 0, res.stderr)
        self.assertIn("First real prompt", res.stdout)

    def _run(self, *args, extra_env=None):
        env = os.environ.copy()
        env["PATH"] = f"{bin_path.parent}:{env.get('PATH', '')}"
        for k in list(env.keys()):
            if "ANTIGRAVITY" in k or "AGY" in k or "GEMINI" in k or "OPENCODE" in k:
                env.pop(k, None)
        empty_brain = Path(self.tmp.name) / "empty_brain"
        empty_brain.mkdir(exist_ok=True)
        env["ANTIGRAVITY_DATA_DIR"] = str(empty_brain)
        env.pop("PROMPT_LOG_HARNESS", None)
        if extra_env:
            env.update(extra_env)
        return subprocess.run(["python3", str(bin_path), "session", *args],
                              cwd=self.repo, capture_output=True, text=True, env=env)

    def test_session_drop_and_restore_claude(self):
        drop = self._run("drop", "1")
        self.assertEqual(drop.returncode, 0, drop.stderr)
        listed = self._run()
        # Prompt 1 now shows as excluded.
        self.assertIn("[EXCLUDED]", listed.stdout)
        restore = self._run("restore", "1")
        self.assertEqual(restore.returncode, 0, restore.stderr)
        listed2 = self._run()
        self.assertNotIn("[EXCLUDED]", listed2.stdout)


